async function ensureNetwork() {
    if (!liveAINetwork) throw new Error('شبكة الذكاء الاصطناعي غير متاحة');
    if (liveAINetwork.status !== 'ALIVE') await liveAINetwork.ignite();
    return liveAINetwork;
}

