'use strict';

function decide(governanceResult = {}) {
  const approved = governanceResult.allowed === true;

  return {
    engine: 'SHEIKHA_DECISION_ENGINE_V1',
    decision: approved ? 'approved' : 'rejected',
    executable: approved,
    reason: approved ? 'Governance passed' : 'Governance rejected',
    governance: governanceResult,
    timestamp: new Date().toISOString()
  };
}

module.exports = { decide };

'use strict';

function evaluateGovernance(request = {}) {
  const action = request.action || 'unknown';
  const actor = request.actor || 'anonymous';

  const blockedActions = ['delete_production', 'disable_governance', 'bypass_policy'];
  const violations = [];

  if (blockedActions.includes(action)) {
    violations.push(`Blocked action: ${action}`);
  }

  return {
    engine: 'SHEIKHA_GOVERNANCE_ENGINE_V1',
    allowed: violations.length === 0,
    actor,
    action,
    principle: 'لا ضرر ولا ضرار',
    checks: {
      identityPresent: Boolean(actor),
      actionPresent: Boolean(action),
      noKnownHarm: violations.length === 0
    },
    violations
  };
}

module.exports = { evaluateGovernance };

'use strict';

const { evaluateGovernance } = require('./governance-engine');
const { decide } = require('./decision-engine');

function runSheikhaProtocol(request = {}) {
  const governance = evaluateGovernance(request);
  const decision = decide(governance);

  return {
    protocol: 'SHEIKHA_PROTOCOL_V1',
    status: decision.executable ? 'READY_TO_EXECUTE' : 'BLOCKED',
    request,
    governance,
    decision
  };
}

module.exports = {
  runSheikhaProtocol,
  evaluateGovernance,
  decide
};

