function test(name, fn) {
    testResults.total++;
    try {
        fn();
        testResults.passed++;
        console.log(`✅ ${name}`);
    } catch (err) {
        testResults.failed++;
        console.error(`❌ ${name}`);
        console.error(`   ${err.message}`);
    }
}

async function asyncTest(name, fn) {
    testResults.total++;
    try {
        await fn();
        testResults.passed++;
        console.log(`✅ ${name}`);
    } catch (err) {
        testResults.failed++;
        console.error(`❌ ${name}`);
        console.error(`   ${err.message}`);
    }
}

function skip(name) {
    testResults.total++;
    testResults.skipped++;
    console.log(`⏭️  ${name} (تم التخطي)`);
}

function assert(condition, message) {
    if (!condition) {
        throw new Error(message || 'فشل الاختبار');
    }
}

